#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/docker/tasks/setup-external-pull.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Build the local images and pull the other images"
# MISE hide=true
# MISE depends=["setup:external:check"]
# MISE tools={uv="latest", python="3.14"}

import os
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# Local services are for development only.
if os.environ.get("MISE_ENV", "") != "dev":
  sys.exit(0)

compose = f"{os.environ['MISE_PROJECT_ROOT']}/.tools/docker-compose.yaml"

helpers.print_header("Getting the images of the local services ...")

helpers.print_subheader("Building the local images ...")
result = helpers.tool("docker", "compose", "--file", compose, "build")
if result.returncode != 0:
  sys.exit(result.returncode)

helpers.print_subheader("Pulling the images ...")
result = helpers.tool("docker", "compose", "--file", compose, "pull", "--ignore-buildable")
sys.exit(result.returncode)
